        /// <summary>"ONLY_OUTDOORS" (without the SPELL_FAILED_ prefix); "code N" when outside the table.</summary>
        public static string Name(int code) { return code >= 0 && code < Table.Length ? Table[code].Name : "code " + code; }

        /// <summary>WoW's text for the code, or null (no GlobalStrings key / needs an argument).</summary>
        public static string Text(int code) { return code >= 0 && code < Table.Length ? Table[code].Text : null; }

        public static int Count { get { return Table.Length; } }

        // ------------------------------------------------------------------ stage O2 (owner spells): the per-result extras and their texts

        /// <summary>Result codes whose SMSG_CAST_FAILED carries extras (Spell::WriteCastResultInfo, Spell.cpp 4709-4807).</summary>
        public const int FailedEquippedItemClass = 29, FailedEquippedItemClassMainhand = 30, FailedEquippedItemClassOffhand = 31, FailedNeedExoticAmmo = 54,
                         FailedNeedMoreItems = 55, FailedReagents = 100, FailedRequiresArea = 101, FailedRequiresSpellFocus = 102, FailedTooManyOfItem = 129,
                         FailedTotemCategory = 130, FailedTotems = 131, FailedPreventedByMechanic = 147, FailedMinSkill = 150, FailedCustomError = 172,
                         FailedFishingTooLow = 181;

        /// <summary>
        /// Reads the uint32 extras AzerothCore writes after the result byte (Spell.cpp 4709-4807): 1 for REQUIRES_SPELL_FOCUS, REQUIRES_AREA,
        /// CUSTOM_ERROR, REAGENTS, PREVENTED_BY_MECHANIC, NEED_EXOTIC_AMMO, FISHING_TOO_LOW; 2 for EQUIPPED_ITEM_CLASS(_MAINHAND / _OFFHAND),
        /// NEED_MORE_ITEMS, MIN_SKILL; TOTEMS / TOTEM_CATEGORY write only the non-zero ones (0..2) and TOO_MANY_OF_ITEM one only when the item has
        /// a limit category - those read what the packet holds. Never more than the packet holds. Returns how many were read.
        /// </summary>
        public static int ReadExtras(WowPacket p, int code, out uint a, out uint b)
        {
            a = 0; b = 0;
            int n;
            switch (code)
            {
                case FailedRequiresSpellFocus: case FailedRequiresArea: case FailedCustomError: case FailedReagents:
                case FailedPreventedByMechanic: case FailedNeedExoticAmmo: case FailedFishingTooLow:
                    n = 1; break;
                case FailedEquippedItemClass: case FailedEquippedItemClassMainhand: case FailedEquippedItemClassOffhand: case FailedNeedMoreItems: case FailedMinSkill:
                    n = 2; break;
                case FailedTotems: case FailedTotemCategory:
                    n = 2; break;
                case FailedTooManyOfItem:
                    n = 1; break;
                default:
                    n = 0; break;
            }
            if (n > p.Remaining / 4) n = p.Remaining / 4;
            if (n >= 1) a = p.U32();
            if (n >= 2) b = p.U32();
            return n;
        }

        /// <summary>
        /// WoW's text for a result with its extras: SPELL_FAILED_CUSTOM_ERROR_&lt;n&gt; (the GlobalStrings key of the SpellCustomErrors value), and
        /// the texts with a %s the client fills from its own DBCs: REQUIRES_SPELL_FOCUS "Requires %s" (SpellFocusObject.dbc name), REQUIRES_AREA
        /// "You need to be in %s." (AreaTable.dbc AreaName), TOTEM_CATEGORY "Requires %s" (TotemCategory.dbc name), PREVENTED_BY_MECHANIC
        /// "Can't do that while %s" (SpellMechanic.dbc StateName). Every other code: Text(code). Null = no WoW text (log only).
        /// </summary>
        public static string Text(int code, uint a, uint b, int extras, WowFiles files)
        {
            string name;
            switch (code)
            {
                case FailedCustomError:
                    return extras > 0 ? CustomErrorText((int)a) : null;
                case FailedRequiresSpellFocus:
                    name = extras > 0 ? DbcName(files, "SpellFocusObject", (int)a, 1) : null;
                    return name != null ? "Requires " + name : null;                    // SPELL_FAILED_REQUIRES_SPELL_FOCUS (GlobalStrings.lua:7156)
                case FailedRequiresArea:
                    name = extras > 0 ? DbcName(files, "AreaTable", (int)a, DbcFields.AreaTable.AreaName_lang) : null;
                    return name != null ? "You need to be in " + name + "." : null;     // SPELL_FAILED_REQUIRES_AREA (GlobalStrings.lua:7155)
                case FailedTotemCategory:
                    name = extras > 0 ? DbcName(files, "TotemCategory", (int)a, 1) : null;
                    return name != null ? "Requires " + name : null;                    // SPELL_FAILED_TOTEM_CATEGORY (GlobalStrings.lua:7197)
                case FailedPreventedByMechanic:
                    name = extras > 0 ? DbcName(files, "SpellMechanic", (int)a, 1) : null;
                    return name != null ? "Can't do that while " + name : null;         // SPELL_FAILED_PREVENTED_BY_MECHANIC (GlobalStrings.lua:7152)
                default:
                    return Text(code);
            }
        }

        /// <summary>A localized name from a DBC row (the enUS slot first), null when the table / row / name is missing.</summary>
        public static string DbcName(WowFiles files, string table, int id, int firstField)
        {
            if (files == null || id <= 0) return null;
            try
            {
                var t = Dbc.Load(files, table);
                if (t == null || firstField + 16 >= t.FieldCount) return null;
                int r = t.FindRow(id);
                if (r < 0) return null;
                string s = t.GetLocalizedString(r, firstField);
